const input = $json;

const traceId = String(input.traceId ?? '').trim();
const channel = String(input.channel ?? '').trim();
const sender = String(input.sender ?? '').trim();
const message = String(input.message ?? '').trim();
const intent = String(input.intent ?? '').trim().toUpperCase();

let valid = true;
const errors = [];

if (!traceId) { valid = false; errors.push('Falta traceId'); }
if (!channel) { valid = false; errors.push('Falta channel'); }
if (!sender) { valid = false; errors.push('Falta sender'); }
if (!message) { valid = false; errors.push('Falta message'); }

if (intent !== 'ATENCION_HUESPED') {
  valid = false;
  errors.push('Intent invalido para Worker Atencion');
}

return {
  json: {
    traceId,
    timestamp: new Date().toISOString(),
    channel,
    sender,
    message,
    intent,
    validation: { valid, errors }
  }
};

const input = $json;

return {
  json: {
    status: 'RECHAZADO',
    approved: false,
    response: null,

    error: {
      code: 'INVALID_WORKER_INPUT',
      message: 'La entrada recibida por el Worker de Atencion no cumple con los campos requeridos.',
      details: input.validation?.errors ?? []
    },

    traceId: input.traceId ?? null,
    timestamp: new Date().toISOString(),

    worker: {
      workflow: 'WF_WORKER_ATENCION',
      stage: 'VALIDACION_ENTRADA'
    }
  }
};

const agent = $json;
const ctx = $('02 - Validar Entrada').first().json;

// Extraer chunks del intermediateSteps del Agent
const steps = agent.intermediateSteps || [];
const chunks = [];

for (const step of steps) {
  const obs = step.observation;
  if (!obs) continue;

  try {
    const parsed = JSON.parse(obs);
    const arr = Array.isArray(parsed) ? parsed : [parsed];
    for (const item of arr) {
      if (item.snippets && Array.isArray(item.snippets)) {
        for (const snippet of item.snippets) {
          if (snippet.content) {
            chunks.push({
              content: String(snippet.content),
              score: snippet.score || null
            });
          }
        }
      }
    }
  } catch (e) {
    chunks.push({
      content: String(obs).slice(0, 3000),
      score: null
    });
  }
}

// Detectar si el mensaje es una queja o pedido especial
const mensaje = String(ctx.message || '');
const esQueja = /\b(no funciona|no anda|roto|rota|no tengo|falta|necesito|pido|solicito|reclamo|queja|problema|falla|aver[ií]a|sucio|sucia|ruido|molestia|p[eé]simo|mal[ií]simo)\b/i.test(mensaje);

return {
  json: {
    traceId: ctx.traceId,
    timestamp: ctx.timestamp,
    channel: ctx.channel,
    sender: ctx.sender,
    message: ctx.message,
    intent: ctx.intent,

    response: agent.output,

    chunks: chunks,
    chunkCount: chunks.length,
    hasContext: chunks.length > 0,

    esQueja: esQueja
  }
};

const judge = $('06 - Judge').first().json.output;

let traceId = null;
try {
  traceId = $('05 - Extraer Contexto').first().json.traceId;
} catch (e) {
  traceId = null;
}

return {
  json: {
    status: 'BLOQUEADO',
    approved: false,
    response: null,

    traceId: traceId,
    timestamp: new Date().toISOString(),

    judge: judge,

    escalation: {
      required: true,
      reason: judge && judge.reason ? judge.reason : 'La respuesta de atención no superó las validaciones de seguridad.'
    },

    worker: {
      workflow: 'WF_WORKER_ATENCION',
      stage: 'ACTION_GATE'
    }
  }
};

const contexto = $('05 - Extraer Contexto').first().json;
const judge = $('06 - Judge').first().json.output;

const texto = String(contexto.response ?? '').trim();
const responseFinal = texto.length > 0
  ? texto
  : 'No pudimos procesar tu consulta en este momento. Por favor, contactá a recepción.';

return {
  json: {
    traceId: contexto.traceId,
    timestamp: new Date().toISOString(),

    channel: contexto.channel,
    sender: contexto.sender,
    message: contexto.message,
    intent: contexto.intent,

    approved: judge.approved,
    response: responseFinal,

    esQueja: contexto.esQueja || false,

    worker: {
      workflow: 'WF_WORKER_ATENCION',
      stage: 'RESPUESTA_FINAL'
    },

    judge: judge
  }
};

const input = $json;

return {
  json: {
    traceId: input.traceId ?? null,
    timestamp: new Date().toISOString(),

    channel: input.channel,
    recipient: input.sender,

    originalMessage: input.message,
    message: input.response,

    approved: input.approved,

    esQueja: input.esQueja || false,

    judge: input.judge ?? null,

    worker: {
      workflow: 'WF_WORKER_ATENCION',
      stage: 'DISPATCH'
    },

    dispatch: {
      ready: true,
      source: 'WF_WORKER_ATENCION'
    }
  }
};

